.cart {
  width: min(640px, 100%);
  margin: 0 auto;
  padding: 0 16px 40px;
  box-sizing: border-box;
  text-align: left;
}

.cart-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--border);
}

.cart-row {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  align-items: center;
  gap: 16px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
}

.cart-name {
  color: var(--text-h);
}

.cart-unit-price,
.cart-quantity {
  font-size: 15px;
}

.cart-stepper {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

