  border-color: var(--accent-border);
  background: var(--accent-bg);
}

.cart-step:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.cart-quantity {
  min-width: 36px;
  text-align: center;
}

