  border-bottom: 1px solid var(--border);
}

.cart-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: 16px;
}

.cart-total strong {
  font-size: 20px;
  color: var(--text-h);
}

